WITH valid AS (SELECT *, CAST(amount AS INT) AS amount_int, CASE WHEN method IN ('card', 'bank_transfer') THEN 'Tier 1' ELSE 'Other' END AS method_group, COALESCE(method, 'NONE') AS method_clean FROM payments WHERE method IS NOT NULL) SELECT *, MIN(amount_int) OVER (PARTITION BY method ORDER BY amount, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_amount_int, AVG(amount_int) OVER (PARTITION BY method ORDER BY amount, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_amount_int, COUNT(amount_int) OVER (PARTITION BY method ORDER BY amount, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_amount_int, CUME_DIST() OVER (PARTITION BY method ORDER BY amount NULLS LAST) AS amount_cume_dist FROM valid
